import { useState } from 'react';
import { downloadSalesReport } from '../../services/reportService';
import './ReportModal.css';

const ReportModal = ({ onClose }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [loading, setLoading] = useState(false);

  const handleDownload = async () => {
    if (!startDate || !endDate) {
      alert('Выберите период');
      return;
    }

    try {
      setLoading(true);

      const blob = await downloadSalesReport(startDate, endDate);

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `sales-report_${startDate}_${endDate}.pdf`;
      a.click();

      window.URL.revokeObjectURL(url);
      onClose();
    } catch (e) {
      console.error(e);
      alert('Ошибка формирования отчёта');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal">
        <h2>Отчёт о продажах</h2>

        <label>
          С:
          <input
            type="date"
            value={startDate}
            onChange={e => setStartDate(e.target.value)}
          />
        </label>

        <label>
          По:
          <input
            type="date"
            value={endDate}
            onChange={e => setEndDate(e.target.value)}
          />
        </label>

        <div className="modal-actions">
          <button onClick={onClose}>Отмена</button>
          <button onClick={handleDownload} disabled={loading}>
            {loading ? 'Формирование…' : 'Скачать PDF'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ReportModal;
